R='/Users/stef/Projects/ehlcodacabana-final/logs/'
combo=collections.defaultdict(set)
for f in glob.glob(R+'runs/*.json'):
    d=json.load(open(f))
    for n in d.get('notes',[]):
        if n.get('what')=='setup':
            p=n.get('profile',{})
            combo[d['case'][5:]].add((n['supplier'], tuple(sorted(p.get('signals',[]))), n.get('near_cost'), n.get('budget')))
for c in sorted(combo):
    print(c)
    for x in sorted(combo[c], key=lambda z:z[0]): print('   ',x[0], list(x[1]), 'near_cost' if x[2] else '', 'budget=%s'%x[3])
